def getClassString(classString, og):
    """ Return the string of the class"""
    if classString in og:
        return og[classString]
    else:
        return None

def getClassStringWithoutPrefix(classString, og):
    """ Return the string of the class without the prefix"""
    if classString in og:
        return og[classString].split(":")[1]
    else:
        return None

def getClassStringWithoutPrefixAndVersion(classString, og):
    """ Return the string of the class without the prefix and version"""
    if classString in og:
        return og[classString].split(":")[1].split("_")[0]
